from itertools import permutations

# Iki is parcacigi, her biri: oku -> arttir -> yaz  (kilitsiz)
# Durum: x (paylasilan), t0, t1 (yerel)
def kos(sira):
    x = 0
    yerel = {0: None, 1: None}
    pc = {0: 0, 1: 0}
    for ip in sira:
        adim = pc[ip]
        if adim == 0:
            yerel[ip] = x                 # oku
        elif adim == 1:
            yerel[ip] = yerel[ip] + 1     # arttir
        else:
            x = yerel[ip]                 # yaz
        pc[ip] += 1
    return x

# 2 is parcacigi x 3 adim -> butun serpistirmeler
siralar = set(permutations([0, 0, 0, 1, 1, 1]))
sonuclar = {}
for s in sorted(siralar):
    r = kos(s)
    sonuclar[r] = sonuclar.get(r, 0) + 1

print("serpistirme sayisi:", len(siralar))
for v in sorted(sonuclar):
    print("  x = {} -> {} serpistirme".format(v, sonuclar[v]))
hatali = sum(n for v, n in sonuclar.items() if v != 2)
print("hatali sonuc veren serpistirme: {}/{} = %{:.1f}".format(
    hatali, len(siralar), 100 * hatali / len(siralar)))
print("tam dolasim kusuru buldu mu:", hatali > 0)
